<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {apiRequest} from '@/api/client'
import type {AiOperationsInsight} from '@/types/api'
import DataChart from '@/components/DataChart.vue'
import MetricCard from '@/components/MetricCard.vue'
import {useDashboardStore} from '@/stores/dashboard'
const data=useDashboardStore();onMounted(()=>data.refresh())
const insight=ref<AiOperationsInsight|null>(null),insightLoading=ref(false),insightError=ref('')
async function analyze(){insightLoading.value=true;insightError.value='';try{insight.value=await apiRequest<AiOperationsInsight>('/api/ai/operations-insight',{method:'POST'})}catch(e){insightError.value=e instanceof Error?e.message:'AI 暂时不可用'}finally{insightLoading.value=false}}
const dates=computed(()=>data.trends?.points.map(x=>x.date.slice(5))??[])
const inbound=computed(()=>data.trends?.points.map(x=>x.inbound)??[]),outbound=computed(()=>data.trends?.points.map(x=>x.outbound)??[]),inventory=computed(()=>data.trends?.points.map(x=>x.inventory)??[])
const trendSeries=computed(()=>[{name:'入库',values:inbound.value,color:'#29c7e8'},{name:'出库',values:outbound.value,color:'#77e6a1'},{name:'库存',values:inventory.value,color:'#7aa7ff',yAxisIndex:1}])
function keys(value?:Record<string,number>){return Object.keys(value??{})}function values(value?:Record<string,number>){return Object.values(value??{})}
function fmt(value:unknown){return Array.isArray(value)?`${value[0]}-${String(value[1]).padStart(2,'0')}-${String(value[2]).padStart(2,'0')} ${String(value[3]??0).padStart(2,'0')}:${String(value[4]??0).padStart(2,'0')}`:String(value??'').replace('T',' ')}
</script>
<template><section class="dashboard page operations-home"><header class="page-heading"><div><p class="eyebrow">OPERATIONS HOME</p><h1>驿站运营首页</h1><p>从 Java API 与 MySQL 实时汇总现场、趋势、分布和活动</p></div><button class="ghost" :disabled="data.loading" @click="data.refresh">刷新数据</button></header><div v-if="data.loading&&!data.summary" class="state-panel">正在同步运营数据…</div><div v-else-if="data.error&&!data.summary" class="state-panel error" role="alert">{{data.error}} <button @click="data.refresh">重试</button></div><template v-else-if="data.summary"><div class="metrics"><MetricCard label="今日入库" :value="data.summary.todayInbound" note="件 / TODAY"/><MetricCard label="今日出库" :value="data.summary.todayOutbound" note="件 / TODAY" accent="#77e6a1"/><MetricCard label="当前库存" :value="data.summary.inventory" note="件 / ON SITE" accent="#7aa7ff"/><MetricCard label="异常件" :value="data.summary.exceptions" note="需要关注" accent="#ff6577"/><MetricCard label="滞留件" :value="data.summary.overdue" note="超过 7 天" accent="#ffbe55"/><MetricCard label="仓位利用率" :value="`${data.summary.slotUtilization}%`" note="ENABLED SLOTS" accent="#b58aff"/></div><article class="home-section action-card ai-insight"><header><div><p class="eyebrow">MAIMAIYA · AGGREGATE DATA ONLY</p><h2>AI 运营洞察</h2></div><button class="primary compact" :disabled="insightLoading" @click="analyze">{{insightLoading?'分析中…':'分析今日运营情况'}}</button></header><p v-if="insightError" class="error" role="alert">{{insightError}} <button class="ghost" @click="analyze">重试</button></p><div v-if="insight" class="dashboard-grid triple"><section><h3>总体总结</h3><p>{{insight.summary}}</p></section><section><h3>风险</h3><ul><li v-for="risk in insight.risks" :key="risk">{{risk}}</li></ul></section><section><h3>运营建议</h3><ul><li v-for="item in insight.recommendations" :key="item">{{item}}</li></ul></section></div><p v-else-if="!insightError" class="muted">仅发送真实聚合统计，不包含手机号、取件码或账号密钥。</p></article><div id="analytics" class="home-section"><header><p class="eyebrow">TRENDS · 14 DAYS</p><h2>流量与库存趋势</h2></header><DataChart title="最近 14 天流量与库存" type="line" :labels="dates" :series="trendSeries" :loading="data.loading"/></div><div v-if="data.distributions" class="home-section"><header><p class="eyebrow">DISTRIBUTIONS</p><h2>业务分布</h2></header><div class="dashboard-grid triple"><DataChart title="快递公司占比" type="donut" :labels="keys(data.distributions.courier)" :values="values(data.distributions.courier)"/><DataChart title="快件状态占比" type="pie" :labels="keys(data.distributions.status)" :values="values(data.distributions.status)"/><DataChart title="异常类型占比" type="pie" :labels="keys(data.distributions.exceptionType)" :values="values(data.distributions.exceptionType)"/><DataChart title="货架利用率 %" type="bar" :labels="keys(data.distributions.shelfUtilization)" :values="values(data.distributions.shelfUtilization)" color="#ff9b5e"/><DataChart title="分区利用率 %" type="bar" :labels="keys(data.distributions.zoneUtilization)" :values="values(data.distributions.zoneUtilization)" color="#b58aff"/><DataChart title="停留时长" type="bar" :labels="keys(data.distributions.dwell)" :values="values(data.distributions.dwell)" color="#ffbe55"/></div></div><div v-if="data.activity" class="home-section activity-grid"><article class="chart-card"><header><span>最近异常</span><small>LIVE DATA</small></header><ol class="activity-list"><li v-for="item in data.activity.recentExceptions" :key="item.id"><b>{{item.exceptionType}} · #{{item.parcelId}}</b><span>{{item.description}}</span><small>{{fmt(item.createdAt)}} · {{item.status}}</small></li></ol></article><article class="chart-card"><header><span>最近操作</span><small>LIVE DATA</small></header><ol class="activity-list"><li v-for="item in data.activity.recentOperations" :key="item.id"><b>{{item.operationType}} · {{item.targetType}} #{{item.targetId}}</b><span>{{item.description}}</span><small>{{fmt(item.createdAt)}}</small></li></ol></article></div></template></section></template>
